"""Finalize the existing one-shot concrete-source review; no model call."""
from pathlib import Path
import datetime,hashlib,json,subprocess
out=Path(__file__).resolve().parent
run=json.loads((out/'grok-skill-implementation-acp-run.json').read_text())
assert 'exitCode' in run and run.get('processReaped'), 'Collector must be terminal first'
rows=subprocess.check_output(['ps','-axo','pid=,ppid=,pgid='],text=True)
own=[list(map(int,line.split())) for line in rows.splitlines() if len(line.split())==3 and int(line.split()[2])==run['ownedPid']]
config=hashlib.sha256(Path('/Users/yoda/.grok/config.toml').read_bytes()).hexdigest()
cleanup={'verifiedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'ownedAgentPid':run['ownedPid'],'matchingOwnedProcessRows':own,'processReaped':run['processReaped'],'isolatedHomeRemoved':run['isolatedHomeRemoved'],'globalConfigSha256':config,'globalConfigUnchanged':config==run['globalConfigSha256Before'],'authContentsRead':False,'authContentsCopied':False,'modelRetryCount':0}
(out/'grok-skill-implementation-cleanup.json').write_text(json.dumps(cleanup,indent=2)+'\n')
meta=run.get('terminal',{}).get('_meta',{});usage=meta.get('usage')
d={'proofScope':'One sanitized concrete implementation packet; model advice only, no provider/customer or application-test work by Grok.','completed':run.get('completed',False),'timedOut':run.get('timedOut',False),'failure':run.get('failure'),'selectedModel':run.get('returnedModelOption'),'selectedEffort':run.get('returnedReasoningEffort'),'actualTerminalModelBuckets':list((usage or {}).get('modelUsage',{})),'terminalUsage':usage,'terminalStopReason':run.get('terminal',{}).get('stopReason'),'terminalAtSeconds':run.get('terminalAtSeconds'),'elapsedIncludingCleanupSeconds':run.get('elapsedSeconds'),'promptBytes':run['promptBytes'],'promptRequests':run['promptRequestsSent'],'toolCallCount':run['toolCallCount'],'permissionRequestCount':run['permissionRequestCount'],'mcp':run.get('observedMcpInitialization'),'mcpServers':run.get('observedMcpServerCount'),'partialAssistantCharacters':len(run.get('assistantText','')),'adjudication':'No completed final answer or terminal usage was returned before the original deadline. No advisory finding or approval is inferred from this timed-out call; internal thoughts and partial output are not used as evidence. Existing local tests are separate evidence.','retryCount':0}
(out/'grok-skill-implementation-disposition.json').write_text(json.dumps(d,indent=2)+'\n')
lines=['# Grok concrete instruction-history implementation review','','**No completed review result.** The original one-shot call reached its 290-second review deadline and was cancelled; no retry was attempted. The voice interruption did not start another call.','',f"Selected model `{d['selectedModel']}`, selected effort `{d['selectedEffort']}`. One {d['promptBytes']}-byte sanitized implementation packet. Elapsed including cleanup: {d['elapsedIncludingCleanupSeconds']} seconds. Actual terminal model bucket, token usage and final stop reason were not returned.",'',d['adjudication'],'','No tool or permission request was observed; reported MCP server/tool counts were zero. The owned process group is independently empty, the process was reaped, the disposable private Grok home was removed, and global configuration hash is unchanged. Cached authentication used an opaque symlink; the collector did not read or copy its contents. These checks are not an OS sandbox claim.','','See the independent suite/report for actual application evidence.']
(out/'grok-skill-implementation-review.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'cleanup':cleanup,'disposition':d},indent=2))
